parameters.jsCode:
// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by media.audio.vo.generate@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before media.audio.vo.generate started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "media.audio.vo.generate",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "media.audio.vo.generate", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// GENERATED budget guard — injected because media.audio.vo.generate declares a cost
// (estimate 20 minor units). A unit that can spend
// money never gets to decide for itself whether it may.
const ESTIMATE = 20;
const e = $json;
const b = e.budget ?? {};
const cap_ = b.cap_minor_units ?? null;
const spent = b.spent_minor_units ?? 0;
if (cap_ !== null && spent + ESTIMATE > cap_) {
  throw new Error('BUDGET_EXCEEDED: ' + (spent + ESTIMATE) + ' would exceed cap ' + cap_ + ' in media.audio.vo.generate');
}
let tier = e.policy?.model_tier_cap ?? 'frontier';
const soft = b.soft_limit_pct ?? 0.8;
if (cap_ !== null && spent + ESTIMATE > cap_ * soft) {
  tier = { frontier: 'standard', standard: 'small', small: 'nano', nano: 'nano' }[tier] ?? 'small';
}
return [{ json: { ...e, policy: { ...(e.policy ?? {}), model_tier_cap: tier }, _budget_reserved: ESTIMATE } }];

const p = $json.payload;
const v = p.profile?.creative?.voice || {};
const MAP = {
  'calm|measured': 'voice_calm_neutral',
  'brisk|explanatory': 'voice_clear_explainer',
  'fast|enthusiastic-but-real': 'voice_energetic_ugc',
  'conversational|straight-talking': 'voice_plain_local'
};
const key = `${v.pace || 'medium'}|${v.style || 'conversational'}`;
const voice_id = p.voice_id || MAP[key] || $env.DEFAULT_VOICE_ID;
const lines = (p.beats || []).map(b => b.spoken).filter(Boolean);
return [{ json: { voice_id, text: p.text || lines.join(' '), lines, locale: $('Envelope In').first().json.locale, stability: 0.45, similarity_boost: 0.75 } }];

// Word-level timings are what let captions and beat cuts land on the right frame.
// Without them the renderer guesses, and the guess is visible.
const a = $json.alignment || {};
const chars = a.characters || [];
const starts = a.character_start_times_seconds || [];
const ends = a.character_end_times_seconds || [];
const words = [];
let cur = '', s = null;
for (let i = 0; i < chars.length; i++) {
  const c = chars[i];
  if (s === null) s = starts[i];
  if (/\s/.test(c)) { if (cur) words.push({ word: cur, start_s: s, end_s: ends[i] }); cur = ''; s = null; }
  else cur += c;
}
if (cur) words.push({ word: cur, start_s: s, end_s: ends[ends.length - 1] });
return [{ json: { words, duration_s: ends[ends.length - 1] || null, word_count: words.length } }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "media.audio.vo.generate",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 20,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "media.audio.vo.generate", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

